// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(address actor, address tokenAddr) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(tokenAddr != address(0) && tokenAddr != actor && tokenAddr != address(c));

        vm.prank(actor);
        c.initialize(
            tokenAddr,
            address(0xdead),
            1e18,
            1e18,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        assertTrue(c.baseToken() == tokenAddr);
    }
}
